static void sl_swap_KeyRecord(struct KeyRecord *r)
{
    sl_swap_ObjectRecord((struct ObjectRecord *) r);
    /* B-033.  The word at 0x80 is a UNION, and the generator resolved it the
     * wrong way: it saw `s8 keyID` first and skipped the word as a byte field.
     * The file's own authority says otherwise - "object block types.txt", type
     * 04 key, annotates offset 0x80 as "lock bit values.  Door locks are masked
     * with these values in order to open them", and its example holds the
     * 32-bit word 00 00 00 06.  bondinv.c:744 is the reader that matters
     * (heldkeyflags |= key->keyflags), and it ANDs the result against
     * DoorRecord.keyflags, which sl_swap_DoorRecord DOES SW32 - so leaving this
     * one unswapped made every locked door unopenable natively.
     *
     * Word 0x80 is the last word of a 0x21-word record, so this stays inside
     * the record.  keyID survives as the wire word's MSB; its one reader
     * (propobj.c check_if_entry_is_collectable) extracts it arithmetically. */
    SW32(r->keyflags);
}

static void sl_swap_CCTVRecord(struct CCTVRecord *r)
{
    s32 i;

    sl_swap_ObjectRecord((struct ObjectRecord *) r);
    SW32(r->lookpad);
    for (i = 0; i < 16; i++) SW32(((u32 *) &r->unk84)[i]);
    SW32(r->unkC4);
    SW32(r->unkC8);
    SW32(r->unkCC);
    SW32(r->unkD0);
    SW32(r->unkD4);
    SW32(r->unkD8);
    SW32(r->unkDC);
    SW32(r->timer);
    SW32(r->convert_to_f32);
    SW32(r->unkE8);
    /* STOP.  The file record is 0x3b words (Action Block Types.txt: "06 3B
     * Camera"), which is what sizepropdef() returns and therefore what the
     * walk below strides by - but sizeof(CCTVRecord) is 63 words.  unkEC,
     * unkF0, unkF4 and unkF8 are the four-word overhang: they are declared by
     * the struct and are NOT in the file.  Swapping them writes into the NEXT
     * record.  Measured on surface: the camera at 0xf5d2c568 overhangs onto
     * the type-5 ALARM at 0xf5d2c654, and SW32 of its header word 01 00 00 05
     * lands 05 00 00 01, turning type 5 into type 1.  The walk then dispatched
     * it to the Door arm, whose SW16(obj)/SW16(pad) on already-word-swapped
     * bytes transposed the pair - and setupDoor called modelLoad(25127) with
     * pad's tag.
     *
     * Every camera in every level did this; only the victim's first wire byte
     * decided whether it crashed.  Counted across the wire data: surface has 1
     * camera and it lands on an ALARM whose byte 0 is 0x01, so type 5 became
     * type 1; surface2 has 4 (last one lands on a PROP -> DOOR); bunker2 has 6
     * (last one lands on an AUTOGUN -> DOOR).  Those are exactly the three
     * levels that segfaulted.  The other victims are TAG records whose byte 0
     * is 0x00, so type 22 became type 0 - a 1-word stride that desynchronised
     * the rest of the walk silently instead of loudly.  facility and dam have
     * no cameras at all, which is why 14 levels booted regardless.
     *
     * Grepped tree-wide: unkEC/unkF0/unkF4/unkF8 appear only in bondtypes.h
     * and here, so nothing in src/ ever reads them.  The N64 reads whatever
     * follows and absorbs it; we must not WRITE it. */
}

