/* Type 23, the watch briefing text.  Word 2 is TWO halfwords, not one word.
 *
 * "7F057104 - return watch text for briefing A0.txt" gives the record as
 *
 *     00000023 0000000x 0000tttt rrrrrrrr
 *     x  menu option to fill      t  text to display
 *     r  RESERVED for pointer to next entry at runtime
 *
 * and the disassembly there reads the ID with `LHU A0,000A (V0)` - a HALFWORD
 * at offset 0x0A - after `LW T6,0004 (V0)` for the menu and `LW V0,000C (V0)`
 * for the next pointer.  That is exactly struct watchMenuObjectiveText, so the
 * swap is written against that rather than the opaque setup_objective_text
 * whose unk08 spans both halves.
 *
 * SW32 over word 2 byte-reverses all four bytes, which does not merely
 * mis-order the ID - it moves it.  MEASURED on facility before this change,
 * every one of the five records:
 *
 *     raw[0x08] = 2b 0c 00 00  ->  reserved=0c2b  text=0000
 *     langGet(text=0000)     = NULL
 *     langGet(reserved=0c2b) = "A R K A N G E L S K"
 *
 * langGet(0) returning NULL is what made get_ptr_text_for_watch_breifing_page
 * fall through to Rare's own "E R R O R\n" default for page 0, which is the
 * stage LOCATION line at the top of the watch briefing pages.  The other four
 * records resolved to the overview, M, Q and Moneypenny texts through the same
 * displaced field, which is the control proving the language tables were
 * loaded and the ID was simply wrong.  The fallback is Rare's and stays; what
 * is fixed is the lookup that should never have failed.
 *
 * The sibling at type 17 (sl_swap_objective_entry) already spells this pair as
 * two SW16s, which is why the objective LIST rendered while its header did
 * not. */
static void sl_swap_watchMenuObjectiveText(struct watchMenuObjectiveText *r)
{
    sl_swap_PropDefHeaderRecord((struct PropDefHeaderRecord *) r);
    SW32(r->menu);
    SW16(r->reserved);
    SW16(r->text);
    SW32(r->nextentry);
}


